281	            + Character.toUpperCase(this.getLastName().charAt(0)) + ".";
282	    }
283	
284	    /**
285	     * The fiscal year a date falls in. The fiscal year starts on 1 July and is identified by the
286	     * calendar year in which it ends: a date in July through December belongs to the fiscal year
287	     * ending the following calendar year, a date in January through June to the fiscal year ending
288	     * that same calendar year.
289	     */
290	    private static int fiscalYearOf(LocalDate date) {
291	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
292	    }
293	
294	    /**
295	     * The owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY} is the last two digits of
296	     * the fiscal year (which starts on 1 July) that the business-day-adjusted {@code registrationDate}
297	     * falls in (e.g. {@code 'FY26'} for a registration date between 1 July 2025 and 30 June 2026).
298	     * Derived from the owner's own {@code registrationDate}; {@code null} until it is set.
299	     */
300	    @Transient
301	    public String getFiscalYear() {
302	        if (this.registrationDate == null) {
303	            return null;
304	        }
305	        return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
306	    }
307	
308	    /**
309	     * The owner's membership number, formatted {@code '<customerCode>-M<YY>'} where {@code YY} is
310	     * the last two digits of the fiscal year carried by the business-day-adjusted registration date
311	     * (e.g. {@code 'NSW-1A2B3C4D-M26'}). Derived from the owner's own fields; {@code null} until both
312	     * the customer code and registration date are set.
313	     */
314	    @Transient
315	    public String getMembershipNumber() {
316	        if (this.customerCode == null || this.registrationDate == null) {
317	            return null;
318	        }
319	        return String.format("%s-M%02d", this.customerCode, fiscalYearOf(this.registrationDate) % 100);
320	    }
321	
322	    /**
323	     * A single Luhn check digit (0-9) computed over the digits contained in the owner's
324	     * {@code customerCode}. Derived from the owner's own fields; {@code null} until the customer
325	     * code is set. The standard Luhn algorithm is applied to the digits of the customer code, from
326	     * right to left, doubling every second digit (subtracting 9 when the doubled value exceeds 9).
327	     */
328	    @Transient
329	    public Integer getCheckDigit() {
330	        if (this.customerCode == null) {
331	            return null;
332	        }
333	        int sum = 0;
334	        boolean dbl = true;
335	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
336	            char c = this.customerCode.charAt(i);
337	            if (c < '0' || c > '9') {
338	                continue;
339	            }
340	            int d = c - '0';
341	            if (dbl) {
342	                d *= 2;
343	                if (d > 9) {
344	                    d -= 9;
345	                }
346	            }
347	            sum += d;
348	            dbl = !dbl;
349	        }
350	        return (10 - (sum % 10)) % 10;
351	    }
352	
353	    /**
354	     * The owner's membership points, a score accumulated from the owner's own fields. It starts at
355	     * 0 and gains: 2 when the owner has an email address; 1 when the owner is unique
356	     * ({@code namesakeCount} is 0); 2 when the owner belongs to a household of 3 or more members
357	     * (the owner together with their pets); and 3 when the owner's tenure spans at least one elapsed
358	     * fiscal year, measured as the difference between the fiscal year of today and the fiscal year of
359	     * {@code registrationDate}. Because a newly created owner has zero elapsed fiscal years of tenure,
360	     * a new owner never earns the tenure points. The score feeds {@link #getMembershipLevel()}.
361	     */
362	    @Transient
363	    public Integer getMembershipPoints() {
364	        int points = 0;
365	        boolean hasEmail = this.email != null && !this.email.isBlank();
366	        if (hasEmail) {
367	            points += 2;
368	        }
369	        boolean unique = this.namesakeCount != null && this.namesakeCount == 0;
370	        if (unique) {
371	            points += 1;
372	        }
373	        int householdSize = 1 + getPetsInternal().size();
374	        if (householdSize >= 3) {
375	            points += 2;
376	        }
377	        boolean tenured = this.registrationDate != null
378	            && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) > 0;
379	        if (tenured) {
380	            points += 3;
381	        }
382	        return points;
383	    }
384	
385	    /**
386	     * The owner's numeric membership level, from 1 to 4. By default it is derived from
387	     * {@link #getMembershipPoints()}: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
388	     * 4 for 6 or more points. When a level has been assigned and stored at creation time (the capped
389	     * level computed against the owner's household), that stored value is returned instead, so the
390	     * level read back for the owner reflects the household ceiling applied when the owner was created.
391	     */
392	    @Transient
393	    public Integer getMembershipLevel() {
394	        if (this.membershipLevel != null) {
395	            return this.membershipLevel;
396	        }
397	        return getDerivedMembershipLevel();
398	    }
399	
400	    /**
401	     * Stores the owner's membership level, overriding the value otherwise derived from the owner's
402	     * membership points. Used at creation time to persist the household-capped level.
403	     */
404	    public void setMembershipLevel(Integer membershipLevel) {
405	        this.membershipLevel = membershipLevel;
406	    }
407	
408	    /**
409	     * The owner's membership level derived purely from {@link #getMembershipPoints()}, before any
410	     * household cap: level 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more
411	     * points.
412	     */
413	    @Transient
414	    public Integer getDerivedMembershipLevel() {
415	        int points = getMembershipPoints();
416	        if (points >= 6) {
417	            return 4;
418	        }
419	        if (points >= 4) {
420	            return 3;
421	        }
422	        if (points >= 2) {
423	            return 2;
424	        }
425	        return 1;
426	    }
427	
428	    /**
429	     * The owner's locality: the canonical region carried by the {@code customerCode}, which is the
430	     * {@code <REGION>} segment preceding its first {@code '-'} (e.g. {@code 'NSW'} for customer code
431	     * {@code 'NSW-1A2B3C4D'}). The region is the one derived from the postcode at creation time and
432	     * baked into the identity. {@code 'UNKNOWN'} when the owner has no customer code yet.
433	     */
434	    @Transient
435	    public String getLocality() {
436	        if (this.customerCode == null) {
437	            return "UNKNOWN";
438	        }
439	        int dash = this.customerCode.indexOf('-');
440	        return dash < 0 ? "UNKNOWN" : this.customerCode.substring(0, dash);
441	    }
442	
443	    /**
444	     * Fixed region-to-timezone lookup mapping each canonical region to its IANA timezone name:
445	     * {@code NSW -> 'Australia/Sydney'}, {@code VIC -> 'Australia/Melbourne'},
446	     * {@code QLD -> 'Australia/Brisbane'}.
447	     */
448	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
449	        "NSW", "Australia/Sydney",
450	        "VIC", "Australia/Melbourne",
451	        "QLD", "Australia/Brisbane");
452	
453	    /**
454	     * The owner's timezone: the IANA name derived from the owner's {@link #getLocality() locality}
455	     * via the fixed region-to-timezone table ({@code NSW -> 'Australia/Sydney'},
456	     * {@code VIC -> 'Australia/Melbourne'}, {@code QLD -> 'Australia/Brisbane'}). {@code null} when
457	     * the locality is not one of these regions.
458	     */
459	    @Transient
460	    public String getTimezone() {
461	        return REGION_TIMEZONE.get(getLocality());
462	    }
463	
464	    /**
465	     * The owner's identity key: a single derived value that consolidates all duplicate detection,
466	     * the lower-case hex SHA-256 digest of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
467	     * The telephone is the stored E.164 value, the email its stored lower-cased form (empty when the
468	     * owner has none), and the final segment the American Soundex code of the owner's last name. Two
469	     * owners are duplicates only when their whole identity keys are equal; because the telephone is
470	     * part of the key, two owners with the same last name and postcode but different telephones have
471	     * different identity keys and are not hard duplicates.
472	     */
473	    @Transient
474	    public String getIdentityKey() {
475	        String telephonePart = this.telephone == null ? "" : this.telephone;
476	        String emailPart = this.email == null ? "" : this.email;
477	        String soundexPart = soundex(this.getLastName());
478	        return HashUtils.sha256Hex(telephonePart + "|" + emailPart + "|" + soundexPart);
479	    }
480	
481	    /**
482	     * The American Soundex code of the owner's last name, used to group similar-sounding surnames for
483	     * soft (possible-duplicate) matching. Derived from the owner's own last name.
484	     */
485	    @Transient
486	    public String getLastNameSoundex() {
487	        return soundex(this.getLastName());
488	    }
489	
490	    /**
491	     * Computes the American Soundex code of a name: its first letter (upper-cased) followed by three
492	     * digits derived from the remaining consonants, with adjacent duplicate codes (and codes separated
493	     * only by {@code H} or {@code W}) collapsed, then zero-padded and truncated to four characters. A
494	     * {@code null} or letter-free value yields an empty string.
495	     *
496	     * @param value the name to encode
497	     * @return the four-character Soundex code, or an empty string
498	     */
499	    private static String soundex(String value) {
500	        if (value == null) {
501	            return "";
502	        }
503	        String letters = value.toUpperCase(Locale.ROOT).replaceAll("[^A-Z]", "");
504	        if (letters.isEmpty()) {
505	            return "";
506	        }
507	        StringBuilder code = new StringBuilder();
508	        code.append(letters.charAt(0));
509	        char previousDigit = soundexDigit(letters.charAt(0));
510	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
511	            char c = letters.charAt(i);
512	            char digit = soundexDigit(c);
513	            if (digit != '0' && digit != previousDigit) {
514	                code.append(digit);
515	            }
516	            if (c != 'H' && c != 'W') {
517	                previousDigit = digit;
518	            }
519	        }
520	        while (code.length() < 4) {
521	            code.append('0');
522	        }
523	        return code.toString();
524	    }
525	
526	    /**
527	     * Maps a single upper-case letter to its Soundex digit, or {@code '0'} for the vowels and the
528	     * letters {@code H}, {@code W} and {@code Y} that carry no Soundex digit.
529	     */
530	    private static char soundexDigit(char c) {
531	        switch (c) {
532	            case 'B': case 'F': case 'P': case 'V':
533	                return '1';
534	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
535	                return '2';
536	            case 'D': case 'T':
537	                return '3';
538	            case 'L':
539	                return '4';
540	            case 'M': case 'N':
541	                return '5';
542	            case 'R':
543	                return '6';
544	            default:
545	                return '0';
546	        }
547	    }
548	
549	    /**
550	     * The owner's preferred contact channel, derived from the owner's own fields:
551	     * {@code 'EMAIL'} when an email address is present, otherwise {@code 'PHONE'}.
552	     */
553	    @Transient
554	    public String getContactPreference() {
555	        boolean hasEmail = this.email != null && !this.email.isBlank();
556	        return hasEmail ? "EMAIL" : "PHONE";
557	    }
558	
559	    /**
560	     * The owner's age band, derived from the owner's own fields: the whole number of years from
561	     * {@code birthDate} to {@code registrationDate} placed into a band — {@code 'MINOR'} when under
562	     * 18, {@code 'ADULT'} when 18 to 64, and {@code 'SENIOR'} when 65 or older. The age is measured
563	     * as of the registration date rather than today, so the band is stable over time. {@code null}
564	     * when the owner has no birth date (or no registration date to measure against).
565	     */
566	    @Transient
567	    public String getAgeBand() {
568	        if (this.birthDate == null || this.registrationDate == null) {
569	            return null;
570	        }
571	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
572	        if (age < 18) {
573	            return "MINOR";
574	        }
575	        if (age < 65) {
576	            return "ADULT";
577	        }
578	        return "SENIOR";
579	    }
580	
581	    protected Set<Pet> getPetsInternal() {
582	        if (this.pets == null) {
583	            this.pets = new HashSet<>();
584	        }
585	        return this.pets;
586	    }
587	
588	    protected void setPetsInternal(Set<Pet> pets) {
589	        this.pets = pets;
590	    }
591	
592	    public List<Pet> getPets() {
593	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
594	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
595	        return Collections.unmodifiableList(sortedPets);
596	    }
597	
598	    public void setPets(List<Pet> pets) {
599	        this.pets = new HashSet<>(pets);
600	    }
601	
602	    public void addPet(Pet pet) {
603	        getPetsInternal().add(pet);
604	        pet.setOwner(this);
605	    }
606	
607	    /**
608	     * Return the Pet with the given name, or null if none found for this Owner.
609	     *
610	     * @param name to test
611	     * @return true if pet name is already in use
612	     */
613	    public Pet getPet(String name) {
614	        return getPet(name, false);
615	    }
616	
617	    /**
618	     * Return the Pet with the given name, or null if none found for this Owner.
619	     *
620	     * @param name to test
621	     * @return true if pet name is already in use
622	     */
623	    public Pet getPet(String name, boolean ignoreNew) {
624	        name = name.toLowerCase();
625	        for (Pet pet : getPetsInternal()) {
626	            if (!ignoreNew || !pet.isNew()) {
627	                String compName = pet.getName();
628	                compName = compName.toLowerCase();
629	                if (compName.equals(name)) {
630	                    return pet;
631	                }
632	            }
633	        }
634	        return null;
635	    }
636	
637	    public Pet getPet(Integer petId) {
638	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
639	    }
640	
641	    @Override
642	    public String toString() {
643	        return new ToStringCreator(this)
644	
645	            .append("id", this.getId())
646	            .append("new", this.isNew())
647	            .append("lastName", this.getLastName())
648	            .append("firstName", this.getFirstName())
649	            .append("address", this.address)
650	            .append("city", this.city)
651	            .append("telephone", this.telephone)
652	            .toString();
653	    }
654	}
